fn inherit_special(r#type: *mut _typeobject, base: *mut _typeobject) {
    // Copying tp_traverse and tp_clear is connected to the GC flags
    if (unsafe { (*r#type).tp_flags }) & 16384u64 == 0
        && (unsafe { (*base).tp_flags }) & 16384u64 != 0
        && ((unsafe { (*r#type).tp_traverse }) == None && (unsafe { (*r#type).tp_clear }) == None)
    {
        type_add_flags(r#type, 16384u64);
        if (unsafe { (*r#type).tp_traverse }) == None {
            unsafe {
                (*r#type).tp_traverse = (*base).tp_traverse;
            }
        }
        if (unsafe { (*r#type).tp_clear }) == None {
            unsafe {
                (*r#type).tp_clear = (*base).tp_clear;
            }
        }
    }
    type_add_flags(r#type, (unsafe { (*base).tp_flags }) & 24u64);
    if (unsafe { (*r#type).tp_basicsize }) == 0 {
        unsafe {
            (*r#type).tp_basicsize = (*base).tp_basicsize;
        }
    }
    // Copy other non-function slots
    COPYVAL!(tp_itemsize, r#type, base);
    COPYVAL!(tp_weaklistoffset, r#type, base);
    COPYVAL!(tp_dictoffset, r#type, base);
    // Setup fast subclass flags
    let mro: *mut _object = lookup_tp_mro(base);
    let mut flags: u64 = 0;
    if is_subtype_with_mro(
        mro,
        base,
        (unsafe { PyExc_BaseException }) as *mut _typeobject,
    ) != 0
    {
        flags |= 1073741824u64;
    } else {
        if is_subtype_with_mro(mro, base, unsafe { core::ptr::addr_of_mut!(PyType_Type) }) != 0 {
            flags |= 2147483648u64;
        } else {
            if is_subtype_with_mro(mro, base, unsafe { core::ptr::addr_of_mut!(PyLong_Type) }) != 0
            {
                flags |= 16777216u64;
            } else {
                if is_subtype_with_mro(mro, base, unsafe { core::ptr::addr_of_mut!(PyBytes_Type) })
                    != 0
                {
                    flags |= 134217728u64;
                } else {
                    if is_subtype_with_mro(mro, base, unsafe {
                        core::ptr::addr_of_mut!(PyUnicode_Type)
                    }) != 0
                    {
                        flags |= 268435456u64;
                    } else {
                        if is_subtype_with_mro(mro, base, unsafe {
                            core::ptr::addr_of_mut!(PyTuple_Type)
                        }) != 0
                        {
                            flags |= 67108864u64;
                        } else {
                            if is_subtype_with_mro(mro, base, unsafe {
                                core::ptr::addr_of_mut!(PyList_Type)
                            }) != 0
                            {
                                flags |= 33554432u64;
                            } else {
                                if is_subtype_with_mro(mro, base, unsafe {
                                    core::ptr::addr_of_mut!(PyDict_Type)
                                }) != 0
                                {
                                    flags |= 536870912u64;
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    // Setup some inheritable flags
    if PyType_HasFeature(base, 4194304u64) != 0 {
        flags |= 4194304u64;
    }
    if PyType_HasFeature(base, 8388608u64) != 0 {
        flags |= 8388608u64;
    }
    type_add_flags(r#type, flags);
}

fn overrides_hash(r#type: *mut _typeobject) -> i32 {
    let dict: *mut _object = lookup_tp_dict(r#type);
    let mut r: i32 = unsafe {
        PyDict_Contains(
            dict,
            core::ptr::addr_of_mut!(
                _PyRuntime
                    .static_objects
                    .singletons
                    .strings
                    .identifiers
                    ._py___eq__
                    ._ascii
                    .ob_base
            ),
        )
    };
    if r == 0 {
        r = unsafe {
            PyDict_Contains(
                dict,
                core::ptr::addr_of_mut!(
                    _PyRuntime
                        .static_objects
                        .singletons
                        .strings
                        .identifiers
                        ._py___hash__
                        ._ascii
                        .ob_base
                ),
            )
        };
    }
    r
}

